# SPDX-License-Identifier: MIT
<# .SYNOPSIS
Read numbered text or search authorized evidence without modifying sources.+#>
[CmdletBinding()]
param([string]$Mode = 'Read', [string]$File, [int]$Start = 1, [int]$Count = 150, [string]$Pattern = '')
$ErrorActionPreference = 'Stop'
if ($File -match 'AGENTS-README-FIRST|TODO\.yaml|\.creds') { throw 'Use the dedicated protected reader or MCP workflow.' }
switch ($Mode) {
    'Read' {
        $lines = [System.IO.File]::ReadAllLines((Resolve-Path -LiteralPath $File).Path)
        Write-Output ('FILE ' + $File + '; lines=' + $lines.Count)
        for ($index = $Start - 1; $index -lt [Math]::Min($lines.Count, $Start - 1 + $Count); $index++) {
            Write-Output ('{0}: {1}' -f ($index + 1), $lines[$index])
        }
    }
    'Search' { & rg -n -- $Pattern $File; if ($LASTEXITCODE -gt 1) { throw 'rg failed' } }
    'Files' { & rg --files --hidden $File; if ($LASTEXITCODE -gt 1) { throw 'rg files failed' } }
    default { throw 'Unknown reader mode' }
}

