[CmdletBinding()]
param([Parameter(Mandatory)][string]$ScriptPath, [string]$Mode = '', [string]$File = '', [int]$Start = 1, [int]$Count = 150, [string]$Pattern = '')
$ErrorActionPreference = 'Stop'
