}
$runExitCode = 0
try {
    & $ScriptPath -Mode $Mode -File $File -Start $Start -Count $Count -Pattern $Pattern
} catch {
    $runExitCode = 1
    throw
} finally {
    [ordered]@{TimestampUtc = [DateTime]::UtcNow.ToString('o'); Command = ('pwsh.exe -NoProfile -NonInteractive -File ' + $ScriptPath); Mode = $Mode; File = $File; Start = $Start; Count = $Count; Pattern = $Pattern; ParserErrors = $parseErrors.Count; AnalyzerWarningsErrors = $diagnostics.Count; ExitCode = $runExitCode} | ConvertTo-Json -Compress | Add-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-r4-commands.jsonl')
}

