# SPDX-License-Identifier: Apache-2.0
<# .SYNOPSIS
Read and record selected numbered spans for cross-reference validation.
#>
[CmdletBinding()]
param([string]$Mode,[string]$File='',[int]$Start=1,[int]$Count=150,[string]$Pattern='')
$ErrorActionPreference='Stop'
$null=$Start,$Count
if($Mode -eq 'DryRun'){Write-Output 'Dry run: no spans read or written.';return}
if($File -match 'AGENTS-README-FIRST|TODO\.yaml|\.creds'){throw 'Protected input path'}
